def add_questions(units):
    for row in ROWS:
        week,*values=row.split('|');u=units[int(week)-1]
        for kind,items in zip(['reading','listening'],[values[:5],values[5:]]):
            prompt,answer,b,c,evidence=items;options=[answer,b,c];n=int(week)%3;options=options[n:]+options[:n]
            u[kind]['questions'].append(dict(id=f'v2-w{int(week):02}-{kind}-reason',prompt=prompt,options=options,correct=options.index(answer),explanation=evidence+' 其他选项改变了原文的条件、范围或事实。',type='inference' if kind=='reading' else 'detail'))
